"""Temporal tower via functional-graph cycle decomposition."""

from __future__ import annotations

from itertools import product
from math import gcd
from typing import Dict, List, Tuple

Cfg = Tuple[int, ...]


def local_rule(rule: int, left: int, centre: int, right: int) -> int:
    """Bit 4l + 2c + r of the Wolfram number."""
    return (rule >> (4 * left + 2 * centre + right)) & 1


def step(rule: int, s: Cfg) -> Cfg:
    """One synchronous update on the ring Z/nZ."""
    n = len(s)
    return tuple(local_rule(rule, s[(i - 1) % n], s[i], s[(i + 1) % n])
                 for i in range(n))


def cycle_spectrum(rule: int, n: int) -> Dict[int, int]:
    """Map {cycle length -> number of cycles} of the automaton on the ring.

    The update is a self-map of the finite set F_2^n, so its functional graph
    is a forest of trees rooted on disjoint cycles.  We walk each orbit until
    it revisits a seen state; if that state belongs to the current walk, the
    tail from its first occurrence is a new cycle.  Total cost O(n 2^n): each
    configuration is visited a bounded number of times.
    """
    seen: Dict[Cfg, int] = {}          # configuration -> id of the walk that saw it
    spectrum: Dict[int, int] = {}
    for walk_id, start in enumerate(product((0, 1), repeat=n)):
        if start in seen:
            continue
        path: List[Cfg] = []
        position: Dict[Cfg, int] = {}
        s = start
        while s not in seen and s not in position:
            position[s] = len(path)
            path.append(s)
            s = step(rule, s)
        if s in position:              # closed a brand-new cycle
            length = len(path) - position[s]
            spectrum[length] = spectrum.get(length, 0) + 1
        for state in path:
            seen[state] = walk_id
    return spectrum


def periodic_counts(rule: int, n: int, kmax: int) -> List[int]:
    """|Per_k(rule, n)| for k = 1..kmax, from the cycle spectrum:
    a configuration satisfies F^k(s) = s exactly when it lies on a cycle whose
    length divides k, so |Per_k| = sum_{d | k} d * (number of d-cycles)."""
    spectrum = cycle_spectrum(rule, n)
    return [sum(length * count for length, count in spectrum.items() if k % length == 0)
            for k in range(1, kmax + 1)]


def zeta_series(rule: int, n: int, kmax: int) -> List[float]:
    """Partial sums of log zeta(t) evaluated formally: the coefficients
    |Per_k| / k of the dynamical zeta function
        zeta(t) = exp( sum_k |Per_k| t^k / k )."""
    return [c / k for k, c in enumerate(periodic_counts(rule, n, kmax), start=1)]


def verify_lattice(rule: int, n: int, kmax: int) -> bool:
    """Check Per_k n Per_l = Per_{gcd(k,l)} by explicit set intersection."""
    levels = {}
    for k in range(1, kmax + 1):
        acc = set()
        for s in product((0, 1), repeat=n):
            t = s
            for _ in range(k):
                t = step(rule, t)
            if t == s:
                acc.add(s)
        levels[k] = acc
    return all(levels[k] & levels[l] == levels[gcd(k, l)]
               for k in range(1, kmax + 1) for l in range(1, kmax + 1))


if __name__ == "__main__":
    n = 8
    print(f"ring size n = {n}\n")
    for rule in (0, 30, 90, 110, 150, 204):
        spectrum = cycle_spectrum(rule, n)
        counts = periodic_counts(rule, n, 8)
        print(f"Rule {rule:>3}: cycle spectrum {dict(sorted(spectrum.items()))}")
        print(f"          |Per_k| for k = 1..8 -> {counts}")
    print(f"\nlattice property on n = 4, k,l <= 6, rule 110: "
          f"{verify_lattice(110, 4, 6)}")
